"""Create a portable, offline HTML review gallery with original screenshots."""
import argparse
import base64
import hashlib
import json
from pathlib import Path
import resource

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ARM · Joint data review</title>
<style>
:root{--bg:#f3f5f8;--ink:#172638;--muted:#566679;--line:#dce3ea;--teal:#087c69;--red:#be374c;--blue:#375ccd}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}button,input,select,textarea{font:inherit}button,select{cursor:pointer}button{background:white;border:1px solid var(--line);border-radius:8px;padding:7px 12px;color:var(--ink)}button:hover{border-color:var(--blue)}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #739bff}header{padding:26px 32px 18px;background:#132638;color:white}header .eyebrow{color:#94d7ce;letter-spacing:2px;font-size:12px}h1{font-size:29px;margin:5px 0 8px;letter-spacing:-.7px}header p{max-width:1050px;color:#c7d3df;margin:6px 0}.stats{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}.stat{background:#22394b;border:1px solid #395063;border-radius:10px;padding:10px 18px;min-width:175px}.stat strong{display:block;font-size:24px}.stat span{font-size:12px;color:#bfd0df}.notice{margin:18px 24px 0;padding:13px 17px;border:1px solid #dbc994;background:#fff8e6;border-radius:9px;color:#634a15}.toolbar{padding:16px 24px;display:flex;gap:10px;flex-wrap:wrap;align-items:end}.filter{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--muted)}.filter select,.filter input{padding:8px;border:1px solid var(--line);border-radius:7px;background:white;color:var(--ink)}#search{min-width:260px}.layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:18px;margin:0 24px 28px}aside{background:white;border:1px solid var(--line);border-radius:12px;overflow:hidden;align-self:start;position:sticky;top:12px}#list{max-height:76vh;overflow:auto}.list-head{padding:13px;border-bottom:1px solid var(--line);font-weight:600}.row{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid #edf0f4;border-radius:0;padding:12px 14px}.row.selected{background:#eaf0ff;border-left:4px solid var(--blue);padding-left:10px}.row small{display:block;color:var(--muted);font-size:11px}.row .task{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:12px}.row .dot{color:var(--teal)}main{min-width:0}.card{background:white;border:1px solid var(--line);border-radius:12px;overflow:hidden;margin-bottom:15px}.cardhead{padding:18px 20px;border-bottom:1px solid var(--line)}.badges{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:8px}.badge{font-size:11px;font-weight:700;border-radius:5px;padding:3px 7px;background:#e9eef5;color:#37516e}.badge.retained{background:#def5eb;color:#076d55}.badge.quarantined{background:#fff0ce;color:#805a07}.badge.excluded{background:#fce4e8;color:#923043}h2{font-size:20px;line-height:1.45;margin:8px 0}.metadata{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.reason{margin-top:10px;padding:10px 12px;background:#f4f6f9;border-left:3px solid #8195ad}.viewer{padding:15px}.viewbar{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:10px;font-size:12px;flex-wrap:wrap}.screen{position:relative;background:#eef1f5;border:1px solid var(--line)}.screen img{display:block;width:100%;height:auto}.screen svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.legend{display:flex;gap:14px}.chosen{color:var(--teal)}.rejected{color:var(--red)}.columns{display:grid;grid-template-columns:1fr 1fr;gap:0}.candidate{min-width:0;padding:18px 20px}.candidate+ .candidate{border-left:1px solid var(--line)}.candidate h3{margin:0 0 8px;font-size:15px}.candidate pre{font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fa;border:1px solid #e6ebf0;padding:12px;border-radius:7px;margin:8px 0;max-height:500px;overflow:auto}.candidate .raw{max-height:430px}.tok{font-size:11px;color:var(--muted)}details{margin:10px 0}summary{cursor:pointer;font-size:13px;font-weight:600}.extra{padding:0 20px 12px}.extra pre{font:12px/1.6 monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto;background:#f5f7fa;padding:12px}#notes{width:100%;min-height:75px;padding:10px;border:1px solid var(--line);border-radius:7px;resize:vertical}.decision{padding:16px 20px}.decisionbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.decisionbar button.active{background:var(--blue);color:white;border-color:var(--blue)}.foot{font-size:11px;color:var(--muted);padding:10px 0}.empty{padding:50px;text-align:center;background:white;border-radius:12px}dialog{max-width:96vw;width:1450px;max-height:95vh;border:0;border-radius:10px;padding:15px}dialog::backdrop{background:#122638c9}dialog img{width:100%;height:auto}#closezoom{position:sticky;top:0;float:right}#navigation{display:flex;gap:8px;align-items:center;justify-content:space-between;margin-bottom:12px}a{color:#375ccd} @media(min-width:1200px){.main-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:16px;align-items:start}.columns{grid-template-columns:1fr}.candidate+.candidate{border-left:0;border-top:1px solid var(--line)}}@media(max-width:850px){header{padding:20px}.layout{grid-template-columns:1fr;margin:0 12px}aside{position:static}#list{max-height:180px}.columns{grid-template-columns:1fr}.candidate+.candidate{border-left:0;border-top:1px solid var(--line)}.toolbar{padding:12px}.notice{margin:12px}.stat{min-width:130px}}
</style></head><body>
<header><div class="eyebrow">OPENWEBRL / ACTION REWARD MODELS</div><h1>Inspect the data before training</h1>
<p>Combined C2 + Piotr teacher selections. Compare the original screenshots, chosen responses, rejected alternatives, and filtering decisions.</p>
<div class="stats" id="stats"></div></header>
<div class="notice"><strong>Review draft · SFT has not been approved or launched.</strong> This gallery samples retained pairs and filter examples; it is not the entire dataset. “Rejected” means not selected by the labeler, not a verified failing action. Your notes are saved in this browser and can be exported; they do not automatically modify the dataset or approve training.</div>
<details style="margin:16px 24px;padding:12px 16px;background:white;border:1px solid #dce3ea;border-radius:9px"><summary>Dataset composition, filtering policy, and remaining checks</summary><div id="datasetInfo"></div></details>
<div class="toolbar">
<label class="filter">Source<select id="source"><option value="">Both sources</option></select></label>
<label class="filter">Filter decision<select id="status"><option value="">All decisions</option></select></label>
<label class="filter">Example type<select id="category"><option value="">All pair types</option></select></label>
<label class="filter">Exclusion reason<select id="reason"><option value="">All reasons</option></select></label>
<label class="filter">Search task / actions<input id="search" placeholder="Search task, site, action, or ID"></label>
<button id="export">Export review notes</button><span class="foot" id="progress"></span>
</div>
<div class="layout"><aside><div class="list-head" id="count"></div><div id="list"></div></aside><main id="main"></main></div>
<dialog id="zoom"><button id="closezoom">Close</button><img id="zoomimg" alt="Original screenshot at full size"></dialog>
<script type="application/json" id="payload">__PAYLOAD__</script>
<script>
'use strict';
const data=JSON.parse(document.getElementById('payload').textContent), all=data.examples, $=id=>document.getElementById(id);
const key='arm-joint-review:'+data.dataset_id; let notes={};try{notes=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){}
let filtered=all, current=0;
const pretty=s=>String(s||'').replaceAll('_',' ');
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
for(const [id,field] of [['source','source'],['status','status'],['category','pair_type'],['reason','reason']]){
 for(const value of [...new Set(all.map(x=>x[field]))].filter(Boolean).sort()){$(id).append(new Option(pretty(value),value))}
 $(id).addEventListener('change',filter);
}
const counts=data.audit.counts;
for(const [label,value] of [['Training pairs',(counts.C2.retained_train||0)+(counts.Piotr.retained_train||0)],['Validation pairs',(counts.C2.retained_validation||0)+(counts.Piotr.retained_validation||0)],['C2 retained',(counts.C2.retained_train||0)+(counts.C2.retained_validation||0)],['Piotr retained',(counts.Piotr.retained_train||0)+(counts.Piotr.retained_validation||0)],['Examples in this gallery',all.length]]){
 const box=element('div',undefined,'stat');box.append(element('strong',value.toLocaleString()),element('span',label));$('stats').append(box)
}
const info=$('datasetInfo');info.append(element('p','One fixed pair per retained state. Training uses the natural source proportions. All coordinate-only alternatives are excluded or quarantined in this draft; ambiguous scroll amounts, wait durations, and final-answer pairs are also withheld.'));for(const source of ['C2','Piotr']){const c=counts[source];info.append(element('p',source+': '+(c.source_states||0)+' source states → '+((c.retained_train||0)+(c.retained_validation||0))+' retained pairs; '+(c.sft_reserve_states||0)+' valid winners in the separate SFT-only reserve.'));const d=data.audit.distributions||{};const mix=Object.entries(d[source+':train']||{}).filter(([k])=>k.startsWith('winner:')).sort((a,b)=>b[1]-a[1]).slice(0,8);info.append(element('p','Training winner actions: '+mix.map(([k,v])=>k.slice(7)+' '+v).join(' · '),'metadata'))}info.append(element('p','Remaining checks: '+(data.audit.remaining_gates||[]).join(' · '),'metadata'));
function save(){try{localStorage.setItem(key,JSON.stringify(notes))}catch(e){}updateProgress()}
function updateProgress(){$('progress').textContent=Object.values(notes).filter(x=>x.decision).length+' examples reviewed'}
function filter(){const q=$('search').value.toLowerCase();filtered=all.filter(x=>(!$('source').value||x.source===$('source').value)&&(!$('status').value||x.status===$('status').value)&&(!$('category').value||x.pair_type===$('category').value)&&(!$('reason').value||x.reason===$('reason').value)&&(!q||[x.task,x.host,x.id,x.chosen.text,x.rejected.text].join(' ').toLowerCase().includes(q)));current=0;render()}
$('search').addEventListener('input',filter);
function drawList(){const list=$('list');list.replaceChildren();$('count').textContent=filtered.length+' matching examples';filtered.forEach((x,i)=>{const b=element('button',undefined,'row'+(i===current?' selected':''));b.append(element('small',x.source+' · '+pretty(x.status)+(notes[x.review_id]?.decision?' · ✓':'')),element('div',x.task,'task'),element('small',pretty(x.reason)));b.onclick=()=>{current=i;render()};list.append(b)})}
function detail(label,text){const d=element('details');d.append(element('summary',label),element('pre',text));return d}
function candidate(x,name,cls){const div=element('div',undefined,'candidate');div.append(element('h3',name,cls),element('div',(x.tokens??'?')+' response tokens · '+(x.action_tokens??'?')+' action/boundary tokens','tok'));div.append(element('pre',JSON.stringify(x.actions,null,2)));const full=detail('Full original actor response',x.text);full.lastChild.className='raw';div.append(full);if(x.validation_error)div.append(element('div','Validation: '+x.validation_error,'rejected'));if(x.finish_provenance)div.append(element('div',pretty(x.finish_provenance),'tok'));if(x.completion_boundary_appended)div.append(element('div','Explicit end-of-turn token appended during preparation.','tok'));return div}
const reasons={eligible:'Retained by the current structural rules. This preference still needs semantic scrutiny.',identical_action:'Same executable action despite different reasoning or response text.',near_coordinates:'Only coordinates differ, within the provisional five-unit threshold.',coordinate_only_review:'Only coordinates differ. Different elements versus the same target has not been established; quarantined pending visual review.',done_vs_done:'Both candidates terminate with an answer. Excluded from this first preference recipe to avoid answer-paraphrase preferences.',scroll_amount_review:'Only scroll magnitude differs; either action may be useful. Quarantined.',wait_duration_review:'Only wait duration differs; preference is ambiguous. Quarantined.',duplicate_loser_action:'Another alternative in this draw already has this executable action.',invalid_loser:'Rejected candidate failed structural, completion, context-length, or token-alignment checks. See the raw response and ledger.',possible_benchmark_overlap_review:'Task resembles an evaluation task and is quarantined pending overlap review.',conflicting_candidate_draw_review:'This draw ID occurs with different candidate sets in the release. The stored label cannot be unambiguously joined; the state is quarantined.',conflicting_duplicate_state_review:'Identical context/image state has conflicting selected actions; quarantined.',duplicate_state:'Identical state and chosen action already represented by another row.'};
function render(){drawList();const main=$('main');main.replaceChildren();if(!filtered.length){main.append(element('div','No examples match these filters.','empty'));return}const x=filtered[current];
 const nav=element('div');nav.id='navigation';const back=element('button','← Previous'),next=element('button','Next →');back.disabled=current===0;next.disabled=current===filtered.length-1;back.onclick=()=>{current--;render()};next.onclick=()=>{current++;render()};nav.append(back,element('span',(current+1)+' / '+filtered.length+' · Use J / K to navigate','metadata'),next);main.append(nav);
 const intro=element('section',undefined,'card'),head=element('div',undefined,'cardhead'),badges=element('div',undefined,'badges');for(const s of [x.source,x.status,x.split||'filter example',x.pair_type])badges.append(element('span',pretty(s),'badge '+s));head.append(badges,element('h2',x.task),element('div',x.id+' · turn '+x.turn+' · '+x.host,'metadata'),element('div',x.label_source,'metadata'),element('div',reasons[x.reason]||pretty(x.reason),'reason'));intro.append(head);main.append(intro);
 const grid=element('div',undefined,'main-grid');main.append(grid);const screenCard=element('section',undefined,'card viewer'),bar=element('div',undefined,'viewbar');const legend=element('div',undefined,'legend');legend.append(element('span','● C = chosen','chosen'),element('span','● R = rejected','rejected'));const label=element('label'),check=element('input');check.type='checkbox';check.checked=true;label.append(check,document.createTextNode(' Show click locations'));const full=element('button','Open original screenshot');bar.append(legend,label,full);screenCard.append(bar);const screen=element('div',undefined,'screen'),img=element('img');const image=data.images[x.images[x.images.length-1].sha256];img.src=image.src;img.alt='Browser screenshot for '+x.task;screen.append(img);const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',`0 0 ${image.width} ${image.height}`);for(const [which,color,actions] of [['C','#00846f',x.chosen.actions],['R','#cc334e',x.rejected.actions]]){actions.forEach((a,i)=>{for(const p of ['point_2d','start_point_2d','end_point_2d']){const point=a.arguments?.[p];if(!Array.isArray(point))continue;const cx=point[0]/1000*image.width,cy=point[1]/1000*image.height;const circle=document.createElementNS(svg.namespaceURI,'circle');for(const [k,v] of Object.entries({cx,cy,r:12,fill:color,'fill-opacity':.18,stroke:color,'stroke-width':3}))circle.setAttribute(k,v);const t=document.createElementNS(svg.namespaceURI,'text');t.setAttribute('x',Math.max(0,Math.min(image.width-35,cx+14)));t.setAttribute('y',Math.max(18,cy-10));t.setAttribute('fill',color);t.setAttribute('stroke','white');t.setAttribute('stroke-width','3');t.setAttribute('paint-order','stroke');t.setAttribute('font-size','18');t.setAttribute('font-weight','bold');t.textContent=which+(i+1);svg.append(circle,t)}})}screen.append(svg);screenCard.append(screen,element('div','Original screenshot. Markers map stored normalized [0,1000] coordinates; numbers follow tool-call order.','foot'));check.onchange=()=>svg.style.display=check.checked?'':'none';full.onclick=()=>{$('zoomimg').src=image.src;$('zoom').showModal()};grid.append(screenCard);
 const responses=element('section',undefined,'card columns');responses.append(candidate(x.chosen,'Chosen · selected candidate','chosen'),candidate(x.rejected,'Rejected · unselected alternative','rejected'));grid.append(responses);
 const extra=element('section',undefined,'card extra');if(x.teacher_reasoning)extra.append(detail('GPT-5.5 judge rationale · metadata, not an SFT target',x.teacher_reasoning));extra.append(detail('Full actor context before the action',x.prompt),detail('Provenance and token-mask positions',JSON.stringify({source_path:x.source_path,draw_id:x.draw_id||x.id,chosen_index:x.chosen_index,rejected_index:x.rejected_index,source_sha256:x.source_sha256,candidate_line_sha256:x.candidate_line_sha256,task_group:x.task_group,prompt_tokens:x.prompt_tokens,image_sha256:x.images.map(i=>i.sha256),chosen_action_token_indices:x.chosen.action_token_indices,rejected_action_token_indices:x.rejected.action_token_indices},null,2)));main.append(extra);
 const decision=element('section',undefined,'card decision');decision.append(element('h3','Your review'));const db=element('div',undefined,'decisionbar');for(const [v,t] of [['usable','Looks usable'],['exclude','Exclude this pair'],['unsure','Unsure'],['','Clear decision']]){const b=element('button',t,notes[x.review_id]?.decision===v?'active':'');b.onclick=()=>{notes[x.review_id]={...notes[x.review_id],decision:v,updated_at:new Date().toISOString()};save();render()};db.append(b)}const input=element('textarea');input.id='notes';input.placeholder='What is wrong or useful here? Mention the intended target, task constraints, or filter rule.';input.value=notes[x.review_id]?.note||'';input.oninput=()=>{notes[x.review_id]={...notes[x.review_id],note:input.value,updated_at:new Date().toISOString()};save()};decision.append(db,input,element('div','Local review notes only. Export the JSON and share it to apply decisions in a new dataset revision.','foot'));main.append(decision);
}
$('closezoom').onclick=()=>$('zoom').close();
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('zoom').open)return;if(e.key==='j'&&current<filtered.length-1){current++;render()}if(e.key==='k'&&current>0){current--;render()}});
$('export').onclick=()=>{const reviewed=all.filter(x=>notes[x.review_id]).map(x=>({review_id:x.review_id,id:x.id,draw_id:x.draw_id,status:x.status,reason:x.reason,chosen_sha256:x.chosen.raw_text_sha256,rejected_sha256:x.rejected.raw_text_sha256,...notes[x.review_id]}));const blob=new Blob([JSON.stringify({dataset_id:data.dataset_id,manifest_sha256:data.audit.artifact_sha256,exported_at:new Date().toISOString(),reviews:reviewed},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='arm-joint-review-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
updateProgress();render();
</script></body></html>'''


def main():
    p=argparse.ArgumentParser();p.add_argument('--data',type=Path,required=True);p.add_argument('--output',type=Path,required=True)
    a=p.parse_args();resource.setrlimit(resource.RLIMIT_AS,(768*1024**2,768*1024**2));resource.setrlimit(resource.RLIMIT_CPU,(60,65))
    audit=json.loads((a.data/'audit.json').read_text())
    examples=[json.loads(l) for l in (a.data/'review-examples.jsonl').open()]
    images={}
    for x in examples:
        x['review_id']=hashlib.sha256((x['id']+x['reason']+x['rejected']['text']).encode()).hexdigest()[:20]
        for img in x['images']:
            if img['sha256'] in images:continue
            raw=Path(img['path']).read_bytes()
            if hashlib.sha256(raw).hexdigest()!=img['sha256']:raise ValueError('review image hash mismatch')
            mime={'PNG':'image/png','JPEG':'image/jpeg','WEBP':'image/webp'}.get(img['format'])
            if not mime:raise ValueError('unsupported review image format')
            images[img['sha256']]={'src':'data:'+mime+';base64,'+base64.b64encode(raw).decode(),'width':img['width'],'height':img['height']}
    payload={'audit':audit,'examples':examples,'images':images,'dataset_id':audit['artifact_sha256']['joint_pairs.train.jsonl']}
    safe=json.dumps(payload,ensure_ascii=True,separators=(',',':')).replace('<','\\u003c')
    a.output.parent.mkdir(parents=True,exist_ok=True)
    a.output.write_text(HTML.replace('__PAYLOAD__',safe))
    print(json.dumps({'html':str(a.output),'examples':len(examples),'images':len(images),'bytes':a.output.stat().st_size}))


if __name__=='__main__':main()
